 ('zerov', 'zero vector', 'vectơ-không', 'a vector whose start and end are the same point.', 'vectơ có điểm đầu và điểm cuối trùng nhau.', '\\(\\overrightarrow{AA}=\\vec0\\).', '\\(\\vec0\\)'),
 ('dirv', 'direction', 'hướng của vectơ', 'the direction the arrow points to.', 'hướng mà mũi tên chỉ tới.', 'The two vectors have the same direction.', ''),
 ('collin', 'collinear vectors', 'cùng phương', 'vectors whose lines are parallel or the same line.', 'hai vectơ có giá song song hoặc trùng nhau.', '\\(\\overrightarrow{AB}\\) and \\(\\overrightarrow{CD}\\) are collinear.', ''),
